script:
frappe.ui.form.on('Ticket', {
    refresh: function(frm) {
        add_visit_history_button(frm);
    },

    patient_id: function(frm) {
        add_visit_history_button(frm);
    }
});

function add_visit_history_button(frm) {

    frm.remove_custom_button(__('Visit History'));

    if (frm.doc.patient_id) {

        frm.add_custom_button(__('Visit History'), function() {

            frappe.set_route(
                'List',
                'Ticket',
                {
                    patient_id: frm.doc.patient_id
                }
            );

        });
    }
}

frappe.ui.form.on('Raise Ticket', {
    refresh(frm) {
        render_pledge(frm);
    },
    user_name(frm) {
        render_pledge(frm);
    }
});

function render_pledge(frm) {
    let name = frm.doc.user_name || "";

    let html = `
        <div style="font-size:15px; line-height:1.6;">
            <p><b>The Specific Pledge:</b></p>
            <p>
                I, 
                <span style="border-bottom:1px solid #000; display:inline-block; min-width:150px; text-align:center;">
                    ${name || "&nbsp;"}
                </span>, 
                pledge that for the next <b>7 days</b>, I will:
            </p>
        </div>
    `;

    frm.fields_dict.the_specific_pledge.$wrapper.html(html);
}

frappe.ui.form.on('Patient', {

    custom_state: function(frm) {
        // Clear district when state changes
        frm.set_value('custom_district', null);

        if (frm.doc.custom_state) {
            // Filter district based on selected state
            frm.set_query('custom_district', function() {
                return {
                    filters: {
                        state: frm.doc.custom_state
                    }
                };
            });
        }
    },

    custom_district: function(frm) {
        if (!frm.doc.custom_state) {
            frappe.msgprint(__('Please select State before selecting District'));
            frm.set_value('custom_district', null);
        }
    },

    onload: function(frm) {
        // Apply filter on load if state already selected
        if (frm.doc.custom_state) {
            frm.set_query('custom_district', function() {
                return {
                    filters: {
                        state: frm.doc.custom_state
                    }
                };
            });
        }
    }

});
